function clampMatrixWidth(value){return Math.max(340,Math.min(480,Math.round(Number(value)||380)));}
function AllocationSplitter({value,onChange}){
  const startDrag=e=>{if(e.button!==0)return;const grid=e.currentTarget.parentElement,startX=e.clientX,startWidth=value,max=Math.max(340,Math.min(480,grid.getBoundingClientRect().width-630));const move=event=>onChange(Math.max(340,Math.min(max,startWidth+startX-event.clientX)));const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);e.preventDefault();};
  const key=e=>{if(e.key==='ArrowLeft'){e.preventDefault();onChange(clampMatrixWidth(value+16));}else if(e.key==='ArrowRight'){e.preventDefault();onChange(clampMatrixWidth(value-16));}else if(e.key==='Home'){e.preventDefault();onChange(380);}};
  return <div className="allocation-splitter" role="separator" aria-label="调整人员沙盘和重点能力矩阵宽度" aria-orientation="vertical" aria-valuemin="340" aria-valuemax="480" aria-valuenow={Math.round(value)} tabIndex="0" onPointerDown={startDrag} onDoubleClick={()=>onChange(380)} onKeyDown={key} title="拖动调整宽度；双击恢复默认"><span/></div>;
}

