    {modal?.type==='person'&&<PersonDetail person={modal.person} state={byState[modal.person.id]} snap={snap} canMove={view==='compact'&&can('allocate')} canStatus={!readOnlyOverview&&can('status.manage')&&mode==='live'&&!!byState[modal.person.id]} onClose={()=>setModal(null)} onMove={async(p,g)=>{const changed=await move(p,g);if(changed){setModal(null);return {ok:true};}return {ok:false,error:lastCommandErrorRef.current||'调配未完成，请稍后重试。'};}} onStatus={kind=>setModal({type:'status',kind,personId:modal.person.id,revision:snap.revision})}/>} 
    {modal?.type==='status'&&<StatusForm snap={snap} model={modal} busy={busy} isSuper={snap.isSuperAdministrator} canManageLocations={can('config.manage')&&!snap.partial} onLocationCommand={command} onClose={()=>setModal(null)} onSave={async data=>{const operation=modal.record?'updateStatus':data.replacesRecordId?'replaceDeployment':'status';if(await command(operation,data))setModal(null);}}/>}
